<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comercios · Rotisería Libre</title><style>body{font-family:system-ui;max-width:1050px;margin:auto;padding:20px;background:#f9f4ed}main,section{background:white;border-radius:10px;padding:18px;margin:18px 0}label{display:block;margin:10px 0}input,textarea,select{padding:9px;max-width:100%}button{padding:9px;background:#9c3824;color:white;border:0;border-radius:6px}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #ddd;padding:9px;text-align:left}</style></head><body><header><h1>🍕 Administración de comercios</h1><p>Solo superadministrador</p><form method="POST" action="/salir">@csrf<button>Cerrar sesión</button></form></header>@if(session('ok'))<p role="status">{{ session('ok') }}</p>@endif<main><h2>Crear comercio</h2><p>Los comercios nuevos permanecen pendientes hasta que los habilites.</p>@if($errors->any())<ul>@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul>@endif<form method="POST" action="/admin/comercios">@csrf<label>Nombre <input name="nombre" maxlength="160" required value="{{ old('nombre') }}"></label><label>Identificador (slug) <input name="slug" pattern="[a-z0-9-]+" maxlength="160" required value="{{ old('slug') }}"></label><label>WhatsApp <input name="telefono_whatsapp" maxlength="30" value="{{ old('telefono_whatsapp') }}"></label><label>Descripción <textarea name="descripcion" maxlength="2000">{{ old('descripcion') }}</textarea></label><button>Crear comercio pendiente</button></form></main><section><h2>Comercios registrados</h2><div style="overflow:auto"><table><thead><tr><th>Comercio</th><th>Identificador</th><th>Estado</th><th>Acción</th></tr></thead><tbody>@foreach($comercios as $comercio)<tr><td>{{ $comercio->nombre }}<details><summary>Asignar comerciante</summary><form method="POST" action="/admin/comercios/{{ $comercio->id }}/usuarios">@csrf<label>Nombre <input name="name" r